def _extract_marker_extras(
    markers: list[Any],
    extras: set[str],
) -> None:
    """Recursively extract extra names from marker comparisons.

    Finds comparisons like ``extra == "foo"`` or ``"foo" == extra`` (both
    ``==`` and ``!=`` operators) and adds the canonicalised extra name to
    *extras*.  Logical operators (``"and"``, ``"or"``) and nested lists are
    traversed; ``"in"`` comparisons are ignored.
    """
    for item in markers:
        if isinstance(item, str):
            # "and" or "or" – skip, just continue traversal
            continue
        if isinstance(item, list):
            _extract_marker_extras(item, extras)
            continue
        # Must be a MarkerItem tuple: (lhs, op, rhs)
        if not isinstance(item, tuple) or len(item) != 3:
            continue
        lhs, op, rhs = item
        if op.serialize() not in ("==", "!="):
            continue
        # Check if one side is the "extra" variable and the other is a Value
        if isinstance(lhs, tuple) and lhs[0].value == "extra" and isinstance(rhs, tuple):
            extras.add(rhs[0].value)
        elif isinstance(rhs, tuple) and rhs[0].value == "extra" and isinstance(lhs, tuple):
            extras.add(lhs[0].value)


